1	import { DatabaseSync } from "node:sqlite";
2	import { randomUUID } from "node:crypto";
3	import { mkdirSync, readFileSync } from "node:fs";
4	import { dirname } from "node:path";
5	import { Group } from "@semaphore-protocol/group";
6	import type {
7	  AuditAction, AuditEvent, GroupVersionSummary, PollDetail, PollResults, PollStatus, PollSummary, VoteReceipt
8	} from "./types.ts";
9	
10	interface SeedPoll extends Omit<PollDetail, "memberCount" | "optionCount" | "eligibleMemberCommitments" | "groupVersion" | "merkleRoot"> {}
11	interface CatalogSeed { polls: SeedPoll[]; memberCommitments: string[] }
12	interface PollRow {
13	  id: string; title: string; summary: string; description: string;
14	  organizer: string; status: PollStatus; published_at: string; closes_at: string;
15	  options_json: string; group_version: number; frozen_version: number | null;
16	}
17	interface GroupVersionRow { poll_id: string; version: number; commitments_json: string; merkle_root: string; created_at: string }
18	interface VoteRow { id: string; poll_id: string; option_id: string; nullifier: string; accepted_at: string }
19	interface AuditRow { id: string; action: AuditAction; poll_id: string; result: "success" | "failure"; at: string; details_json: string }
20	
21	export interface GroupSnapshot { version: number; commitments: string[]; merkleRoot: string }
22	export type GroupOperation =
23	  | { type: "join"; commitment: string }
24	  | { type: "rotate"; oldCommitment: string; newCommitment: string }
25	  | { type: "revoke"; commitment: string };
26	export type GroupOperationOutcome =
27	  | { ok: true; group: GroupVersionSummary }
28	  | { ok: false; reason: "poll_missing" | "poll_not_editable" | "group_frozen" | "group_version_changed" | "duplicate_commitment" | "commitment_not_found" | "empty_group" };
29	export type CommitVoteOutcome =
30	  | { ok: true; receipt: VoteReceipt }
31	  | { ok: false; reason: "poll_closed" | "invalid_option" | "duplicate_nullifier" | "group_version_changed" };
32	
33	export interface NewPollInput {
34	  id: string;
35	  title: string;
36	  summary: string;
37	  description: string;
38	  organizer: string;
39	  publishedAt: string;
40	  closesAt: string;
41	  options: { id: string; label: string }[];
42	  commitments: string[];
43	}
44	export type CreatePollOutcome =
45	  | { ok: true; poll: PollDetail }
46	  | { ok: false; reason: "poll_exists" };
47	/** Legal lifecycle edges, in order. */
48	const STATUS_FLOW: Record<PollStatus, PollStatus | null> = {
49	  draft: "open",
50	  open: "closed",
51	  closed: "archived",
52	  archived: null
53	};
54	export const STATUSES: readonly PollStatus[] = ["draft", "open", "closed", "archived"];
55	export type StatusTransitionOutcome =
56	  | { ok: true; status: PollStatus }
57	  | { ok: false; reason: "poll_missing" | "invalid_status" | "status_conflict" | "illegal_transition" };
58	
59	function toReceipt(row: VoteRow): VoteReceipt {
60	  return { id: row.id, pollId: row.poll_id, optionId: row.option_id, nullifier: row.nullifier, acceptedAt: row.accepted_at };
61	}
62	function toSnapshot(row: GroupVersionRow): GroupSnapshot {
63	  return { version: row.version, commitments: JSON.parse(row.commitments_json) as string[], merkleRoot: row.merkle_root };
64	}
65	function toAuditEvent(row: AuditRow): AuditEvent {
66	  return { id: row.id, action: row.action, pollId: row.poll_id, result: row.result, at: row.at, details: JSON.parse(row.details_json) as Record<string, unknown> };
67	}
68	function merkleRootOf(commitments: string[]): string {
69	  return new Group(commitments).root.toString();
70	}
71	
72	export function openCatalog(databasePath: string) {
73	  if (databasePath !== ":memory:") mkdirSync(dirname(databasePath), { recursive: true });
74	  const db = new DatabaseSync(databasePath);
75	  db.exec(`
76	    PRAGMA foreign_keys = ON;
77	    PRAGMA journal_mode = WAL;
78	    CREATE TABLE IF NOT EXISTS polls (
79	      id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL,
80	      description TEXT NOT NULL, organizer TEXT NOT NULL, status TEXT NOT NULL,
81	      published_at TEXT NOT NULL, closes_at TEXT NOT NULL, options_json TEXT NOT NULL
82	    );
83	    CREATE TABLE IF NOT EXISTS members (
84	      commitment TEXT PRIMARY KEY, position INTEGER NOT NULL UNIQUE
85	    );
86	    CREATE TABLE IF NOT EXISTS votes (
87	      id TEXT PRIMARY KEY,
88	      poll_id TEXT NOT NULL REFERENCES polls (id),
89	      option_id TEXT NOT NULL,
90	      nullifier TEXT NOT NULL,
91	      accepted_at TEXT NOT NULL
92	    );
93	    CREATE UNIQUE INDEX IF NOT EXISTS votes_poll_nullifier ON votes (poll_id, nullifier);
94	    CREATE TABLE IF NOT EXISTS group_versions (
95	      poll_id TEXT NOT NULL REFERENCES polls (id),
96	      version INTEGER NOT NULL,
97	      commitments_json TEXT NOT NULL,
98	      merkle_root TEXT NOT NULL,
99	      created_at TEXT NOT NULL,
100	      PRIMARY KEY (poll_id, version)
101	    );
102	    CREATE INDEX IF NOT EXISTS group_versions_root ON group_versions (poll_id, merkle_root);
103	    CREATE TABLE IF NOT EXISTS audit_events (
104	      id TEXT PRIMARY KEY,
105	      action TEXT NOT NULL,
106	      poll_id TEXT NOT NULL,
107	      result TEXT NOT NULL,
108	      at TEXT NOT NULL,
109	      details_json TEXT NOT NULL
110	    );
111	    CREATE INDEX IF NOT EXISTS audit_events_time ON audit_events (at DESC, id DESC);
112	  `);
113	  // Migrate pre-versioning databases: add the group columns to existing polls.
114	  const pollColumns = new Set((db.prepare("PRAGMA table_info(polls)").all() as { name: string }[]).map(column => column.name));
115	  if (!pollColumns.has("group_version")) db.exec("ALTER TABLE polls ADD COLUMN group_version INTEGER NOT NULL DEFAULT 1");
116	  if (!pollColumns.has("frozen_version")) db.exec("ALTER TABLE polls ADD COLUMN frozen_version INTEGER");
117	
118	  const existing = db.prepare("SELECT count(*) AS count FROM polls").get() as { count: number };
119	  if (existing.count === 0) {
120	    const seed = JSON.parse(readFileSync(new URL("../fixtures/catalog.json", import.meta.url), "utf8")) as CatalogSeed;
121	    db.exec("BEGIN");
122	    try {
123	      const insertPoll = db.prepare("INSERT INTO polls (id, title, summary, description, organizer, status, published_at, closes_at, options_json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
124	      for (const poll of seed.polls) insertPoll.run(poll.id, poll.title, poll.summary, poll.description, poll.organizer, poll.status, poll.publishedAt, poll.closesAt, JSON.stringify(poll.options));
125	      const insertMember = db.prepare("INSERT INTO members VALUES (?, ?)");
126	      seed.memberCommitments.forEach((commitment, index) => insertMember.run(commitment, index));
127	      db.exec("COMMIT");
128	    } catch (error) { db.exec("ROLLBACK"); db.close(); throw error; }
129	  }
130	  // Legacy databases only ever knew the "open" state: normalize any poll whose
131	  // status is not part of the lifecycle to open, so old issues migrate forward.
132	  db.exec(`UPDATE polls SET status = 'open' WHERE status NOT IN ('draft', 'open', 'closed', 'archived')`);
133	  // Snapshot the legacy member list as immutable version 1 for every poll that
134	  // has no versions yet (fresh seeds and databases migrated from before
135	  // versioned groups). The snapshot, its Merkle root and the version number
136	  // are persisted together so all three stay consistent across restarts.
137	  const versioned = db.prepare("SELECT count(*) AS count FROM group_versions").get() as { count: number };
138	  if (versioned.count === 0) {
139	    const commitments = members();
140	    if (commitments.length > 0) {
141	      const merkleRoot = merkleRootOf(commitments);
142	      const createdAt = new Date().toISOString();
143	      const insertVersion = db.prepare("INSERT INTO group_versions (poll_id, version, commitments_json, merkle_root, created_at) VALUES (?, 1, ?, ?, ?)");
144	      const pollIds = db.prepare("SELECT id FROM polls").all() as { id: string }[];
145	      db.exec("BEGIN");
146	      try {
147	        for (const poll of pollIds) insertVersion.run(poll.id, JSON.stringify(commitments), merkleRoot, createdAt);
148	        // Polls that already accepted votes are frozen on version 1, matching
149	        // the freeze-on-first-vote rule applied to new votes.
150	        db.exec("UPDATE polls SET frozen_version = 1 WHERE frozen_version IS NULL AND id IN (SELECT DISTINCT poll_id FROM votes)");
151	        db.exec("COMMIT");
152	      } catch (error) { db.exec("ROLLBACK"); db.close(); throw error; }
153	    }
154	  }
155	
156	  /** Insert an audit row. Must be called inside an open transaction. */
157	  function insertAudit(action: AuditAction, pollId: string, result: "success" | "failure", details: Record<string, unknown>, atIso: string) {
158	    db.prepare("INSERT INTO audit_events (id, action, poll_id, result, at, details_json) VALUES (?, ?, ?, ?, ?, ?)")
159	      .run(randomUUID(), action, pollId, result, atIso, JSON.stringify(details));
160	  }
161	  /** Persist an audit event for an authorized request whose change did not commit (validation/business failure). */
162	  function recordAudit(action: AuditAction, pollId: string, result: "failure", details: Record<string, unknown>, now = Date.now()) {
163	    insertAudit(action, pollId, result, details, new Date(now).toISOString());
164	  }
165	  function members(): string[] {
166	    return (db.prepare("SELECT commitment FROM members ORDER BY position").all() as { commitment: string }[]).map(row => row.commitment);
167	  }
168	  function pollRow(id: string): PollRow | undefined {
169	    return db.prepare("SELECT * FROM polls WHERE id = ?").get(id) as PollRow | undefined;
170	  }
171	  /**
172	   * Lazily persists the deadline transition for every open poll whose
173	   * closesAt has passed. Each status change and its audit row commit in one
174	   * transaction; a no-op read starts no write transaction. commitVote repeats
175	   * this check inside its own transaction, which is the authoritative
176	   * adjudication for a vote racing the cutoff.
177	   */
178	  function closeExpired(now = Date.now()) {
179	    const open = db.prepare("SELECT id, closes_at FROM polls WHERE status = 'open'").all() as { id: string; closes_at: string }[];
180	    const due = open.filter(row => now >= Date.parse(row.closes_at)).map(row => row.id);
181	    if (due.length === 0) return;
182	    db.exec("BEGIN IMMEDIATE");
183	    try {
184	      const at = new Date(now).toISOString();
185	      for (const pollId of due) {
186	        const result = db.prepare("UPDATE polls SET status = 'closed' WHERE id = ? AND status = 'open'").run(pollId);
187	        if (result.changes > 0) insertAudit("poll_status_change", pollId, "success", { from: "open", to: "closed", reason: "deadline" }, at);
188	      }
189	      db.exec("COMMIT");
190	    } catch (error) { db.exec("ROLLBACK"); throw error; }
191	  }
192	  function currentSnapshot(pollId: string): GroupSnapshot | undefined {
193	    const row = db.prepare(`
194	      SELECT gv.* FROM polls p
195	      JOIN group_versions gv ON gv.poll_id = p.id AND gv.version = p.group_version
196	      WHERE p.id = ?
197	    `).get(pollId) as GroupVersionRow | undefined;
198	    return row ? toSnapshot(row) : undefined;
199	  }
200	  function summarize(row: PollRow): PollSummary {
201	    return {
202	      id: row.id, title: row.title, summary: row.summary, organizer: row.organizer,
203	      status: row.status, publishedAt: row.published_at, closesAt: row.closes_at,
204	      memberCount: currentSnapshot(row.id)?.commitments.length ?? 0, optionCount: JSON.parse(row.options_json).length
205	    };
206	  }
207	  return {
208	    /** Public catalog hides drafts; an authorized manager can list them too. */
209	    list(now = Date.now(), includeDrafts = false): PollSummary[] {
210	      closeExpired(now);
211	      const rows = db.prepare(includeDrafts ? "SELECT * FROM polls ORDER BY published_at DESC, id" : "SELECT * FROM polls WHERE status != 'draft' ORDER BY published_at DESC, id").all() as unknown as PollRow[];
212	      return rows.map(summarize);
213	    },
214	    get(id: string, now = Date.now()): PollDetail | undefined {
215	      closeExpired(now);
216	      const row = pollRow(id);
217	      if (!row) return undefined;
218	      const snapshot = currentSnapshot(id);
219	      if (!snapshot) return undefined;
220	      return {
221	        ...summarize(row), description: row.description, options: JSON.parse(row.options_json),
222	        eligibleMemberCommitments: snapshot.commitments, groupVersion: snapshot.version, merkleRoot: snapshot.merkleRoot
223	      };
224	    },
225	    /**
226	     * Creates a poll in draft with its immutable version-1 member snapshot.
227	     * The insert, the snapshot and the success audit row commit together; a
228	     * conflicting id aborts everything (the caller audits that failure).
229	     */
230	    createPoll(input: NewPollInput, now = Date.now()): CreatePollOutcome {
231	      db.exec("BEGIN IMMEDIATE");
232	      try {
233	        if (pollRow(input.id)) { db.exec("ROLLBACK"); return { ok: false, reason: "poll_exists" }; }
234	        const at = new Date(now).toISOString();
235	        db.prepare(`
236	          INSERT INTO polls (id, title, summary, description, organizer, status, published_at, closes_at, options_json, group_version, frozen_version)
237	          VALUES (?, ?, ?, ?, ?, 'draft', ?, ?, ?, 1, NULL)
238	        `).run(input.id, input.title, input.summary, input.description, input.organizer, input.publishedAt, input.closesAt, JSON.stringify(input.options));
239	        const merkleRoot = merkleRootOf(input.commitments);
240	        db.prepare("INSERT INTO group_versions (poll_id, version, commitments_json, merkle_root, created_at) VALUES (?, 1, ?, ?, ?)")
241	          .run(input.id, JSON.stringify(input.commitments), merkleRoot, at);
242	        insertAudit("poll_create", input.id, "success", { optionCount: input.options.length, memberCount: input.commitments.length }, at);
243	        db.exec("COMMIT");
244	        const poll = this.get(input.id);
245	        if (!poll) throw new Error("Created poll could not be read back");
246	        return { ok: true, poll };
247	      } catch (error) {
248	        db.exec("ROLLBACK");
249	        throw error;
250	      }
251	    },
252	    /**
253	     * Applies a lifecycle transition draft→open→closed→archived with an
254	     * optimistic expectedStatus guard. The status update and its audit row
255	     * commit atomically; conflicts and illegal edges leave a failure event.
256	     */
257	    transitionStatus(pollId: string, target: PollStatus, expectedStatus: PollStatus, now = Date.now()): StatusTransitionOutcome {
258	      db.exec("BEGIN IMMEDIATE");
259	      // Every authorized attempt leaves an event; failures commit only the audit row.
260	      const reject = (reason: Exclude<StatusTransitionOutcome, { ok: true }>["reason"], actual?: PollStatus): StatusTransitionOutcome => {
261	        db.exec("ROLLBACK");
262	        recordAudit(
263	          "status_change_rejected", pollId, "failure",
264	          { requested: target, expected: expectedStatus, reason, ...(actual ? { actual } : {}) },
265	          now
266	        );
267	        return { ok: false, reason };
268	      };
269	      try {
270	        const row = pollRow(pollId);
271	        if (!row) return reject("poll_missing");
272	        if (!STATUSES.includes(target) || !STATUSES.includes(expectedStatus)) return reject("invalid_status", row.status);
273	        if (row.status !== expectedStatus) return reject("status_conflict", row.status);
274	        if (STATUS_FLOW[row.status] !== target) return reject("illegal_transition", row.status);
275	        const at = new Date(now).toISOString();
276	        db.prepare("UPDATE polls SET status = ? WHERE id = ?").run(target, pollId);
277	        insertAudit("poll_status_change", pollId, "success", { from: row.status, to: target }, at);
278	        db.exec("COMMIT");
279	        return { ok: true, status: target };
280	      } catch (error) {
281	        db.exec("ROLLBACK");
282	        throw error;
283	      }
284	    },
285	    /** Record an authorized management request that failed before changing data (malformed payload, etc.). */
286	    auditFailure(action: AuditAction, pollId: string, details: Record<string, unknown>, now = Date.now()): void {
287	      recordAudit(action, pollId, "failure", details, now);
288	    },
289	    /** The immutable snapshot a poll currently points at, or a specific historical version. */
290	    groupSnapshot(pollId: string, version?: number): GroupSnapshot | undefined {
291	      if (version === undefined) return currentSnapshot(pollId);
292	      const row = db.prepare("SELECT * FROM group_versions WHERE poll_id = ? AND version = ?").get(pollId, version) as GroupVersionRow | undefined;
293	      return row ? toSnapshot(row) : undefined;
294	    },
295	    /** The snapshot whose Merkle root matches, used to place proofs from clients that omit groupVersion. */
296	    groupSnapshotByRoot(pollId: string, merkleRoot: string): GroupSnapshot | undefined {
297	      const row = db.prepare("SELECT * FROM group_versions WHERE poll_id = ? AND merkle_root = ? ORDER BY version DESC LIMIT 1").get(pollId, merkleRoot) as GroupVersionRow | undefined;
298	      return row ? toSnapshot(row) : undefined;
299	    },
300	    /**
301	     * Applies a membership change as a new immutable version. Membership may
302	     * only be edited while the poll is a draft, or while open with no votes
303	     * yet (the first vote freezes the version). The optimistic
304	     * expectedVersion check, the status/frozen checks and the pointer update
305	     * happen in one immediate transaction, so a concurrent vote either freezes
306	     * the group first (this then fails with group_frozen) or observes the new
307	     * version. Successful changes and rejected attempts are both audited.
308	     */
309	    applyGroupOperation(pollId: string, operation: GroupOperation, expectedVersion: number, now = Date.now()): GroupOperationOutcome {
310	      db.exec("BEGIN IMMEDIATE");
311	      // Business failures roll the (never-applied) change back but still leave
312	      // a failure audit event, committed on its own after the rollback.
313	      const reject = (reason: Exclude<GroupOperationOutcome, { ok: true }>["reason"], status?: PollStatus): GroupOperationOutcome => {
314	        db.exec("ROLLBACK");
315	        recordAudit(
316	          "group_change_rejected", pollId, "failure",
317	          { operation: operation.type, expectedVersion, reason, ...(status ? { status } : {}) },
318	          now
319	        );
320	        return { ok: false, reason };
321	      };
322	      try {
323	        const row = pollRow(pollId);
324	        if (!row) return reject("poll_missing");
325	        // An open poll past its deadline is semantically closed: persist the
326	        // deadline transition (with the rejected-edit event) and refuse it.
327	        if (row.status === "open" && now >= Date.parse(row.closes_at)) {
328	          const at = new Date(now).toISOString();
329	          db.prepare("UPDATE polls SET status = 'closed' WHERE id = ?").run(pollId);
330	          insertAudit("poll_status_change", pollId, "success", { from: "open", to: "closed", reason: "deadline" }, at);
331	          insertAudit("group_change_rejected", pollId, "failure", { operation: operation.type, expectedVersion, reason: "poll_not_editable", status: "closed", deadline: true }, at);
332	          db.exec("COMMIT");
333	          return { ok: false, reason: "poll_not_editable" };
334	        }
335	        const editable = row.status === "draft" || (row.status === "open" && row.frozen_version === null);
336	        if (!editable) return reject(row.status === "open" ? "group_frozen" : "poll_not_editable", row.status);
337	        if (row.group_version !== expectedVersion) return reject("group_version_changed", row.status);
338	        const snapshot = currentSnapshot(pollId);
339	        if (!snapshot) return reject("poll_missing");
340	        const commitments = [...snapshot.commitments];
341	        if (operation.type === "join") {
342	          if (commitments.includes(operation.commitment)) return reject("duplicate_commitment", row.status);
343	          commitments.push(operation.commitment);
344	        } else if (operation.type === "rotate") {
345	          const index = commitments.indexOf(operation.oldCommitment);
346	          if (index === -1) return reject("commitment_not_found", row.status);
347	          if (commitments.includes(operation.newCommitment)) return reject("duplicate_commitment", row.status);
348	          commitments[index] = operation.newCommitment;
349	        } else {
350	          const index = commitments.indexOf(operation.commitment);
351	          if (index === -1) return reject("commitment_not_found", row.status);
352	          if (commitments.length === 1) return reject("empty_group", row.status);
353	          commitments.splice(index, 1);
354	        }
355	        const version = expectedVersion + 1;
356	        const merkleRoot = merkleRootOf(commitments);
357	        const at = new Date(now).toISOString();
358	        db.prepare("INSERT INTO group_versions (poll_id, version, commitments_json, merkle_root, created_at) VALUES (?, ?, ?, ?, ?)")
359	          .run(pollId, version, JSON.stringify(commitments), merkleRoot, at);
360	        db.prepare("UPDATE polls SET group_version = ? WHERE id = ?").run(version, pollId);
361	        insertAudit("group_change", pollId, "success", { operation: operation.type, expectedVersion, version, memberCount: commitments.length }, at);
362	        db.exec("COMMIT");
363	        return { ok: true, group: { pollId, version, merkleRoot, memberCount: commitments.length, commitments } };
364	      } catch (error) {
365	        db.exec("ROLLBACK");
366	        throw error;
367	      }
368	    },
369	    /**
370	     * Re-validates the poll state, confirms the group version is still current,
371	     * freezes that version on the first accepted vote, rejects a reused
372	     * nullifier and persists the vote in a single immediate transaction; the
373	     * UNIQUE (poll_id, nullifier) index is the backstop against concurrent
374	     * duplicates and deduplicates across versions. When the deadline has
375	     * passed the poll is persisted as closed in that same transaction, so a
376	     * vote racing the cutoff is adjudicated by the transaction and rejected.
377	     */
378	    commitVote(pollId: string, optionId: string, nullifier: string, groupVersion: number, now = Date.now()): CommitVoteOutcome {
379	      db.exec("BEGIN IMMEDIATE");
380	      try {
381	        const row = pollRow(pollId);
382	        if (!row) { db.exec("ROLLBACK"); return { ok: false, reason: "poll_closed" }; }
383	        if (row.status !== "open") { db.exec("ROLLBACK"); return { ok: false, reason: "poll_closed" }; }
384	        if (now >= Date.parse(row.closes_at)) {
385	          // Atomic deadline transition: persist closed and refuse the out-of-window vote.
386	          const at = new Date(now).toISOString();
387	          db.prepare("UPDATE polls SET status = 'closed' WHERE id = ?").run(pollId);
388	          insertAudit("poll_status_change", pollId, "success", { from: "open", to: "closed", reason: "deadline" }, at);
389	          db.exec("COMMIT");
390	          return { ok: false, reason: "poll_closed" };
391	        }
392	        if (row.group_version !== groupVersion) { db.exec("ROLLBACK"); return { ok: false, reason: "group_version_changed" }; }
393	        const options = JSON.parse(row.options_json) as { id: string }[];
394	        if (!options.some(option => option.id === optionId)) { db.exec("ROLLBACK"); return { ok: false, reason: "invalid_option" }; }
395	        const duplicate = db.prepare("SELECT 1 AS found FROM votes WHERE poll_id = ? AND nullifier = ?").get(pollId, nullifier);
396	        if (duplicate) { db.exec("ROLLBACK"); return { ok: false, reason: "duplicate_nullifier" }; }
397	        const receipt: VoteReceipt = { id: randomUUID(), pollId, optionId, nullifier, acceptedAt: new Date(now).toISOString() };
398	        db.prepare("INSERT INTO votes (id, poll_id, option_id, nullifier, accepted_at) VALUES (?, ?, ?, ?, ?)")
399	          .run(receipt.id, receipt.pollId, receipt.optionId, receipt.nullifier, receipt.acceptedAt);
400	        if (row.frozen_version === null) db.prepare("UPDATE polls SET frozen_version = ? WHERE id = ?").run(groupVersion, pollId);
401	        db.exec("COMMIT");
402	        return { ok: true, receipt };
403	      } catch (error) {
404	        db.exec("ROLLBACK");
405	        if (error instanceof Error && error.message.includes("UNIQUE")) return { ok: false, reason: "duplicate_nullifier" };
406	        throw error;
407	      }
408	    },
409	    /** Results stay public for open/closed/archived polls; drafts have none. */
410	    results(pollId: string, now = Date.now()): PollResults | undefined {
411	      closeExpired(now);
412	      const row = pollRow(pollId);
413	      if (!row || row.status === "draft") return undefined;
414	      const counts = new Map(
415	        (db.prepare("SELECT option_id, count(*) AS count FROM votes WHERE poll_id = ? GROUP BY option_id").all(pollId) as { option_id: string; count: number }[])
416	          .map(entry => [entry.option_id, entry.count])
417	      );
418	      const options = (JSON.parse(row.options_json) as { id: string }[]).map(option => ({ id: option.id, count: counts.get(option.id) ?? 0 }));
419	      return { pollId, total: options.reduce((sum, option) => sum + option.count, 0), options };
420	    },
421	    receipt(id: string): VoteReceipt | undefined {
422	      const row = db.prepare("SELECT * FROM votes WHERE id = ?").get(id) as VoteRow | undefined;
423	      return row ? toReceipt(row) : undefined;
424	    },
425	    /** Audit trail, newest first; persisted in SQLite so it survives restarts. */
426	    auditEvents(limit = 200): AuditEvent[] {
427	      const rows = db.prepare("SELECT * FROM audit_events ORDER BY at DESC, id DESC LIMIT ?").all(limit) as unknown as AuditRow[];
428	      return rows.map(toAuditEvent);
429	    },
430	    close() { db.close(); }
431	  };
432	}
