1	import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
2	import { existsSync, readFileSync, statSync } from "node:fs";
3	import { extname, resolve, sep } from "node:path";
4	import { timingSafeEqual } from "node:crypto";
5	import { verifyProof, type SemaphoreProof } from "@semaphore-protocol/proof";
6	import { openCatalog, STATUSES, type GroupOperation, type NewPollInput } from "./store.ts";
7	import { isCommitment, isProofPayload, terminateProverWorkers, textToField } from "./voting.ts";
8	import type { AuditEvent, PollStatus } from "./types.ts";
9	
10	const MAX_BODY_BYTES = 1_000_000;
11	
12	export interface AppOptions {
13	  /** When unset (or empty) every administrative request is refused with 401. */
14	  adminToken?: string;
15	}
16	
17	function readBody(request: IncomingMessage): Promise<string> {
18	  return new Promise((resolvePromise, rejectPromise) => {
19	    const chunks: Buffer[] = [];
20	    let size = 0;
21	    request.on("data", (chunk: Buffer) => {
22	      size += chunk.length;
23	      if (size > MAX_BODY_BYTES) { rejectPromise(new Error("body_too_large")); request.destroy(); return; }
24	      chunks.push(chunk);
25	    });
26	    request.on("end", () => resolvePromise(Buffer.concat(chunks).toString("utf8")));
27	    request.on("error", rejectPromise);
28	  });
29	}
30	
31	function isNonEmptyString(value: unknown, maxLength = 2000): value is string {
32	  return typeof value === "string" && value.trim().length > 0 && value.length <= maxLength;
33	}
34	function isIsoDate(value: unknown): value is string {
35	  return typeof value === "string" && Number.isFinite(Date.parse(value));
36	}
37	
38	export function createApp(databasePath: string, publicPath = resolve("dist/public"), options: AppOptions = {}) {
39	  const catalog = openCatalog(databasePath);
40	  const adminToken = options.adminToken && options.adminToken.length > 0 ? options.adminToken : undefined;
41	  let proverUsed = false;
42	  const mime: Record<string, string> = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8", ".svg": "image/svg+xml", ".json": "application/json; charset=utf-8" };
43	  const server = createServer((request, response) => {
44	    handle(request, response).catch(() => {
45	      if (!response.headersSent) response.writeHead(500, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
46	      response.end(JSON.stringify({ error: "internal_error" }));
47	    });
48	  });
49	  server.on("close", () => {
50	    catalog.close();
51	    // Release the snarkjs worker pool so the process can exit.
52	    if (proverUsed) void terminateProverWorkers();
53	  });
54	  return server;
55	
56	  /**
57	   * Authorization gate for management endpoints. A missing, wrong or
58	   * unconfigured token is refused with 401 admin_unauthorized. The check
59	   * runs before the body is read and never mutates data or writes audit.
60	   */
61	  function isAuthorized(request: IncomingMessage): boolean {
62	    if (!adminToken) return false;
63	    const provided = request.headers["x-admin-token"];
64	    if (typeof provided !== "string") return false;
65	    const expected = Buffer.from(adminToken);
66	    const actual = Buffer.from(provided);
67	    return expected.length === actual.length && timingSafeEqual(expected, actual);
68	  }
69	
70	  async function handle(request: IncomingMessage, response: ServerResponse) {
71	    function json(status: number, payload: unknown, headers: Record<string, string> = {}) {
72	      response.writeHead(status, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", ...headers });
73	      response.end(JSON.stringify(payload));
74	    }
75	    function requireAdmin(): boolean {
76	      if (isAuthorized(request)) return true;
77	      json(401, { error: "admin_unauthorized" });
78	      return false;
79	    }
80	    const url = new URL(request.url ?? "/", "http://localhost");
81	    const segments = url.pathname.split("/").filter(Boolean);
82	    if (segments[0] === "api") {
83	      const method = request.method ?? "GET";
84	      if (url.pathname === "/api/health") {
85	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
86	        return json(200, { service: "veilvote", status: "ok" });
87	      }
88	      if (segments[1] === "admin" && segments[2] === "audit" && segments.length === 3) {
89	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
90	        if (!requireAdmin()) return;
91	        return json(200, { events: catalog.auditEvents() });
92	      }
93	      if (segments[1] === "polls" && segments.length <= 4) {
94	        if (segments.length === 2) {
95	          // Public catalog list; creating a poll is admin-only and starts in draft.
96	          if (method === "GET") return json(200, { polls: catalog.list(Date.now(), isAuthorized(request)) });
97	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "GET, POST" });
98	          if (!requireAdmin()) return;
99	          let body: unknown;
100	          try { body = JSON.parse(await readBody(request)); }
101	          catch {
102	            catalog.auditFailure("poll_create", "unknown", { reason: "invalid_json" });
103	            return json(400, { error: "invalid_json" });
104	          }
105	          const parsed = parseNewPoll(body);
106	          if (!parsed.ok) {
107	            catalog.auditFailure("poll_create", parsed.pollId, { reason: parsed.reason });
108	            return json(400, { error: parsed.reason });
109	          }
110	          const outcome = catalog.createPoll(parsed.input);
111	          if (!outcome.ok) {
112	            catalog.auditFailure("poll_create", parsed.input.id, { reason: "poll_exists" });
113	            return json(409, { error: "poll_exists" });
114	          }
115	          return json(201, { poll: outcome.poll });
116	        }
117	        let id: string;
118	        try { id = decodeURIComponent(segments[2]); }
119	        catch { return json(400, { error: "invalid_poll_id" }); }
120	        if (segments.length === 3) {
121	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
122	          const poll = catalog.get(id);
123	          // Drafts are invisible to ordinary detail requests; an authorized
124	          // manager can still read them to prepare the opening.
125	          if (!poll || (poll.status === "draft" && !isAuthorized(request))) return json(404, { error: "poll_not_found" });
126	          return json(200, { poll });
127	        }
128	        if (segments[3] === "results") {
129	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
130	          const result = catalog.results(id);
131	          return result ? json(200, { result }) : json(404, { error: "poll_not_found" });
132	        }
133	        if (segments[3] === "status") {
134	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
135	          if (!requireAdmin()) return;
136	          let body: unknown;
137	          try { body = JSON.parse(await readBody(request)); }
138	          catch {
139	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_json" });
140	            return json(400, { error: "invalid_json" });
141	          }
142	          if (typeof body !== "object" || body === null) {
143	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_status" });
144	            return json(400, { error: "invalid_status" });
145	          }
146	          const { status, expectedStatus } = body as { status?: unknown; expectedStatus?: unknown };
147	          if (!isStatus(status) || !isStatus(expectedStatus)) {
148	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_status", requested: String(status), expected: String(expectedStatus) });
149	            return json(400, { error: "invalid_status" });
150	          }
151	          const outcome = catalog.transitionStatus(id, status, expectedStatus);
152	          if (!outcome.ok) {
153	            if (outcome.reason === "poll_missing") return json(404, { error: "poll_not_found" });
154	            if (outcome.reason === "invalid_status") return json(400, { error: "invalid_status" });
155	            return json(409, { error: outcome.reason });
156	          }
157	          const poll = catalog.get(id);
158	          return json(200, { status: outcome.status, poll });
159	        }
160	        if (segments[3] === "group") {
161	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
162	          if (!requireAdmin()) return;
163	          let body: unknown;
164	          try { body = JSON.parse(await readBody(request)); }
165	          catch {
166	            catalog.auditFailure("group_change_rejected", id, { reason: "invalid_json" });
167	            return json(400, { error: "invalid_json" });
168	          }
169	          if (typeof body !== "object" || body === null) {
170	            catalog.auditFailure("group_change_rejected", id, { reason: "invalid_group_operation" });
171	            return json(400, { error: "invalid_group_operation" });
172	          }
173	          const { operation, expectedVersion, commitment, oldCommitment, newCommitment } = body as Record<string, unknown>;
174	          if (!Number.isInteger(expectedVersion) || (expectedVersion as number) < 1) {
175	            catalog.auditFailure("group_change_rejected", id, { operation: String(operation), reason: "invalid_group_operation" });
176	            return json(400, { error: "invalid_group_operation" });
177	          }
178	          let groupOperation: GroupOperation;
179	          if (operation === "join" && isCommitment(commitment)) groupOperation = { type: "join", commitment };
180	          else if (operation === "rotate" && isCommitment(oldCommitment) && isCommitment(newCommitment)) groupOperation = { type: "rotate", oldCommitment, newCommitment };
181	          else if (operation === "revoke" && isCommitment(commitment)) groupOperation = { type: "revoke", commitment };
182	          else {
183	            catalog.auditFailure("group_change_rejected", id, { operation: String(operation), reason: "invalid_group_operation" });
184	            return json(400, { error: "invalid_group_operation" });
185	          }
186	          const outcome = catalog.applyGroupOperation(id, groupOperation, expectedVersion as number);
187	          if (!outcome.ok) {
188	            if (outcome.reason === "poll_missing") return json(404, { error: "poll_not_found" });
189	            if (outcome.reason === "group_frozen" || outcome.reason === "group_version_changed" || outcome.reason === "poll_not_editable") return json(409, { error: outcome.reason });
190	            return json(400, { error: outcome.reason });
191	          }
192	          return json(201, { group: outcome.group });
193	        }
194	        if (segments[3] === "votes") {
195	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
196	          const poll = catalog.get(id);
197	          // Drafts are invisible to the public (404), matching detail/results.
198	          if (!poll || poll.status === "draft") return json(404, { error: "poll_not_found" });
199	          let body: unknown;
200	          try { body = JSON.parse(await readBody(request)); }
201	          catch { return json(400, { error: "invalid_json" }); }
202	          if (typeof body !== "object" || body === null) return json(400, { error: "invalid_vote" });
203	          const { optionId, proof, groupVersion } = body as { optionId?: unknown; proof?: unknown; groupVersion?: unknown };
204	          if (typeof optionId !== "string" || optionId.length === 0 || !isProofPayload(proof)) {
205	            return json(400, { error: "invalid_vote" });
206	          }
207	          if (groupVersion !== undefined && (!Number.isInteger(groupVersion) || (groupVersion as number) < 1)) {
208	            return json(400, { error: "invalid_vote" });
209	          }
210	          if (!poll.options.some(option => option.id === optionId)) return json(400, { error: "unknown_option" });
211	          // Only open polls before their deadline accept votes. Drafts and
212	          // closed/archived polls answer poll_closed; results stay public.
213	          if (poll.status !== "open" || Date.now() >= Date.parse(poll.closesAt)) return json(409, { error: "poll_closed" });
214	          // Resolve the immutable snapshot the proof must bind to: either the
215	          // explicitly requested version, or the version whose Merkle root the
216	          // proof carries (legacy clients that omit groupVersion). Historical
217	          // versions conflict; unknown roots are unprocessable.
218	          let snapshotVersion: number;
219	          if (groupVersion !== undefined) {
220	            if (groupVersion !== poll.groupVersion) return json(409, { error: "group_version_changed" });
221	            if (proof.merkleTreeRoot !== poll.merkleRoot) return json(422, { error: "proof_binding_mismatch" });
222	            snapshotVersion = groupVersion as number;
223	          } else {
224	            const snapshot = catalog.groupSnapshotByRoot(poll.id, proof.merkleTreeRoot);
225	            if (!snapshot) return json(422, { error: "unknown_merkle_root" });
226	            if (snapshot.version !== poll.groupVersion) return json(409, { error: "group_version_changed" });
227	            snapshotVersion = snapshot.version;
228	          }
229	          // The proof must also be bound to this poll (scope) and the chosen
230	          // option (message).
231	          let bound = false;
232	          try {
233	            bound = proof.scope === textToField(poll.id) && proof.message === textToField(optionId);
234	          } catch { bound = false; }
235	          if (!bound) return json(422, { error: "proof_binding_mismatch" });
236	          let valid = false;
237	          proverUsed = true;
238	          try { valid = await verifyProof(proof as unknown as SemaphoreProof); }
239	          catch { valid = false; }
240	          if (!valid) return json(422, { error: "invalid_proof" });
241	          // Snapshot confirmation, freeze-on-first-vote, nullifier dedup and
242	          // the vote write commit atomically; a concurrent group change makes
243	          // exactly one of the two succeed. A vote racing closesAt is rejected
244	          // as the poll is persisted closed in that same transaction.
245	          const outcome = catalog.commitVote(poll.id, optionId, proof.nullifier, snapshotVersion);
246	          if (!outcome.ok) {
247	            if (outcome.reason === "duplicate_nullifier") return json(409, { error: "duplicate_nullifier" });
248	            if (outcome.reason === "group_version_changed") return json(409, { error: "group_version_changed" });
249	            if (outcome.reason === "poll_closed") return json(409, { error: "poll_closed" });
250	            return json(400, { error: "unknown_option" });
251	          }
252	          return json(201, { receipt: outcome.receipt });
253	        }
254	      }
255	      if (segments[1] === "receipts" && segments.length === 3) {
256	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
257	        let id: string;
258	        try { id = decodeURIComponent(segments[2]); }
259	        catch { return json(400, { error: "invalid_receipt_id" }); }
260	        const receipt = catalog.receipt(id);
261	        return receipt ? json(200, { receipt }) : json(404, { error: "receipt_not_found" });
262	      }
263	      return json(404, { error: "not_found" });
264	    }
265	    if (request.method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
266	    let relativePath: string;
267	    try { relativePath = decodeURIComponent(url.pathname); }
268	    catch { return json(400, { error: "invalid_path" }); }
269	    const file = resolve(publicPath, relativePath === "/" ? "index.html" : `.${relativePath}`);
270	    if (!file.startsWith(`${resolve(publicPath)}${sep}`) || !existsSync(file) || !statSync(file).isFile()) return json(404, { error: "not_found" });
271	    response.writeHead(200, { "Content-Type": mime[extname(file)] ?? "application/octet-stream", "X-Content-Type-Options": "nosniff" });
272	    response.end(readFileSync(file));
273	  }
274	}
275	
276	function isStatus(value: unknown): value is PollStatus {
277	  return typeof value === "string" && (STATUSES as readonly string[]).includes(value);
278	}
279	
280	type ParsePollResult =
281	  | { ok: true; input: NewPollInput }
282	  | { ok: false; reason: string; pollId: string };
283	
284	/**
285	 * Validates a draft creation payload: all existing poll fields, a non-empty
286	 * list of distinct member commitments and at least two options with unique
287	 * ids. Returns a machine-readable error code on failure.
288	 */
289	function parseNewPoll(body: unknown): ParsePollResult {
290	  if (typeof body !== "object" || body === null) return { ok: false, reason: "invalid_poll", pollId: "unknown" };
