6	import type { Server } from "node:http";
7	import { Identity } from "@semaphore-protocol/identity";
8	import { createApp } from "../src/app.ts";
9	import { openCatalog } from "../src/store.ts";
10	import type { AuditEvent, PollDetail } from "../src/types.ts";
11	
12	const ADMIN_TOKEN = "test-admin-token";
13	const adminHeaders = { "Content-Type": "application/json", "X-Admin-Token": ADMIN_TOKEN };
14	const fakeProof = {
15	  merkleTreeDepth: 20, merkleTreeRoot: "1", message: "1", nullifier: "2", scope: "3",
16	  points: ["1", "2", "3", "4", "5", "6", "7", "8"]
