19	async function serve(databasePath: string, token?: string): Promise<{ server: Server; base: string }> {
20	  const server = createApp(databasePath, undefined, { adminToken: token });
21	  await new Promise<void>(done => server.listen(0, "127.0.0.1", done));
22	  const address = server.address();
23	  assert.ok(address && typeof address !== "string");
24	  return { server, base: `http://127.0.0.1:${address.port}` };
25	}
26	async function stop(server: Server) {
27	  server.closeAllConnections();
28	  await new Promise<void>((done, reject) => server.close(error => error ? reject(error) : done()));
29	}
30	async function seedPoll(base: string, overrides: Record<string, unknown> = {}, token = ADMIN_TOKEN) {
31	  const seeded = await (await fetch(`${base}/api/polls/community-garden-autumn`)).json() as { poll: PollDetail };
32	  const payload = {
33	    id: "draft-topic",
34	    title: "新议题", summary: "摘要", description: "描述", organizer: "组织方",
35	    publishedAt: "2026-09-18T08:00:00Z", closesAt: "2026-10-15T12:00:00Z",
36	    options: [{ id: "a", label: "甲" }, { id: "b", label: "乙" }],
37	    commitments: seeded.poll.eligibleMemberCommitments,
38	    ...overrides
39	  };
40	  const response = await fetch(`${base}/api/polls`, { method: "POST", headers: { ...adminHeaders, "X-Admin-Token": token }, body: JSON.stringify(payload) });
41	  return { response, payload };
42	}
43	async function postStatus(base: string, id: string, body: unknown, token?: string) {
44	  const response = await fetch(`${base}/api/polls/${encodeURIComponent(id)}/status`, {
45	    method: "POST",
46	    headers: token === undefined ? adminHeaders : { "Content-Type": "application/json", ...(token ? { "X-Admin-Token": token } : {}) },
47	    body: JSON.stringify(body)
48	  });
49	  return { status: response.status, body: await response.json() as { error?: string; status?: string } };
50	}
51	
52	test("admin endpoints require X-Admin-Token and never write or audit when unauthorized", async () => {
53	  const { server, base } = await serve(":memory:", ADMIN_TOKEN);
54	  try {
55	    const before = (await (await fetch(`${base}/api/polls`)).json() as { polls: unknown[] }).polls.length;
56	
57	    // No token configured on this server at all.
58	    const locked = await serve(":memory:", undefined);
59	    try {
60	      for (const init of [
61	        ["POST", "/api/polls", "{}"],
62	        ["POST", "/api/polls/community-garden-autumn/group", "{}"],
63	        ["POST", "/api/polls/community-garden-autumn/status", "{}"],
64	        ["GET", "/api/admin/audit", null]
65	      ] as const) {
66	        const response = await fetch(`${locked.base}${init[1]}`, { method: init[0], body: init[2] ?? undefined });
67	        assert.equal(response.status, 401);
68	        assert.equal((await response.json() as { error: string }).error, "admin_unauthorized");
69	      }
70	    } finally { await stop(locked.server); }
71	
72	    // Token configured: missing and wrong headers are both 401 on every managed route.
73	    for (const path of ["/api/polls", "/api/polls/community-garden-autumn/group", "/api/polls/community-garden-autumn/status", "/api/admin/audit"]) {
74	      const missing = await fetch(`${base}${path}`, { method: path.endsWith("audit") ? "GET" : "POST", headers: { "Content-Type": "application/json" }, body: path.endsWith("audit") ? undefined : "{}" });
75	      assert.equal(missing.status, 401, path);
76	      const wrong = await fetch(`${base}${path}`, { method: path.endsWith("audit") ? "GET" : "POST", headers: { "Content-Type": "application/json", "X-Admin-Token": "nope" }, body: path.endsWith("audit") ? undefined : "{}" });
77	      assert.equal(wrong.status, 401, path);
78	    }
79	
80	    // A rejected creation wrote nothing; unauthorized attempts left no audit rows.
81	    assert.equal((await (await fetch(`${base}/api/polls`)).json() as { polls: unknown[] }).polls.length, before);
82	    const audit = await fetch(`${base}/api/admin/audit`, { headers: { "X-Admin-Token": ADMIN_TOKEN } }).then(r => r.json()) as { events: AuditEvent[] };
83	    assert.equal(audit.events.length, 0);
84	  } finally { await stop(server); }
85	});
86	
87	test("draft creation validates fields and conflicts on id", async () => {
88	  const { server, base } = await serve(":memory:", ADMIN_TOKEN);
89	  try {
