function computeCloseSnapshot(pollRow: PollRow, closedAt: string): CloseSnapshot {
  const counts = new Map(...votes...);
  const options = (JSON.parse(pollRow.options_json) as {id:string}[]).map(o => ({id: o.id, count: counts.get(o.id) ?? 0}));
  const total = options.reduce((s,o)=>s+o.count,0);
  const head = { pollId: pollRow.id, groupVersion: pollRow.group_version, total, options, closedAt };
  const digest = createHash("sha256").update(JSON.stringify(head), "utf8").digest("hex");
  return { ...head, digest };
}
```

